const inputData = $input.all();
const logs = inputData[0].json.logs;

// 1. Sort logs chronologically
const sortedLogs = logs.sort((a, b) => new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime());

const stats = {
  total_executions: 0,
  max_concurrency: 0,
  avg_processing_time_ms: 0,
  avg_queue_wait_time_ms: 0,
  throughput_per_minute: {},
  worker_efficiency: {}
};

const activeJobs = new Map(); // Track timing for each execution ID
let currentRunning = 0;
const completedDurations = [];
const waitTimes = [];

for (const log of sortedLogs) {
  const msg = log.message;
  const timestamp = new Date(log.timestamp).getTime();
  const minuteKey = log.timestamp.substring(0, 16); // YYYY-MM-DDTHH:mm

  // Extract IDs
  const execMatch = msg.match(/execution (\d+)/);
  if (!execMatch) continue;
  const id = execMatch[1];

  if (!activeJobs.has(id)) {
    activeJobs.set(id, { enqueued: null, started: null, finished: null });
  }
  const job = activeJobs.get(id);

  // Phase 1: Enqueued
  if (msg.includes("Enqueued")) {
    job.enqueued = timestamp;
  }
  // Phase 2: Worker Started
  else if (msg.includes("Worker started")) {
    job.started = timestamp;
    currentRunning++;
    if (currentRunning > stats.max_concurrency) stats.max_concurrency = currentRunning;

    if (job.enqueued) {
      waitTimes.push(timestamp - job.enqueued);
    }
  }
  // Phase 3: Worker Finished
  else if (msg.includes("Worker finished")) {
    job.finished = timestamp;
    currentRunning = Math.max(0, currentRunning - 1);

    if (job.started) {
      completedDurations.push(timestamp - job.started);
    }

    // Track throughput
    stats.throughput_per_minute[minuteKey] = (stats.throughput_per_minute[minuteKey] || 0) + 1;
  }
}

// Final Calculations
const sum = (arr) => arr.reduce((a, b) => a + b, 0);
stats.total_executions = completedDurations.length;
stats.avg_processing_time_ms = Math.round(sum(completedDurations) / completedDurations.length) || 0;
stats.avg_queue_wait_time_ms = Math.round(sum(waitTimes) / waitTimes.length) || 0;

return stats;

// This is a "Blocking" sleep. 
// It keeps the worker slot BUSY for 5 seconds.
const start = Date.now();
while (Date.now() - start < 5000) {
    // Doing nothing, just burning time and holding the slot
}

return { status: "Done after 5s of blocking work" };

